        file_write: function () {}
    }, mocks || {});
    requireMap['./common/trackers.js'] = loadTrackersSr(allMocks);
    if (loaderOverride) requireMap['./configLoader.js'] = loaderOverride;
    return loadModule(
        'js/storyTestAutomationRework.js',
        makeRequire(requireMap),
        allMocks
